#include "calibration/smile_calibration.h"

#include <gmock/gmock.h>
#include <gtest/gtest.h>

#include <cmath>
#include <string_view>
#include <vector>

#include "absl/status/status.h"

namespace smileexplorer {
namespace {

const std::vector<double> kExpiries{0.25, 0.5, 1.0, 2.0};

std::vector<double> strikes(double from, double to, double step) {
  std::vector<double> out;
  for (double k = from; k <= to + 1e-9; k += step) out.push_back(k);
  return out;
}

// Quotes generated by an SSVI surface.
SmileQuotes ssviQuotes(double rate, double rho, double eta, double gamma) {
  SmileQuotes q{.spot = 100,
                .rate = rate,
                .expiries = kExpiries,
                .strikes = strikes(70, 130, 5)};
  const std::vector<double> atm{0.22, 0.20, 0.19, 0.185};
  std::vector<double> thetas;
  for (size_t i = 0; i < atm.size(); ++i) {
    thetas.push_back(atm[i] * atm[i] * kExpiries[i]);
  }
  const SsviSurface surface(rho, eta, gamma, kExpiries, thetas);
  for (double t : kExpiries) {
    for (double k : q.strikes) {
      q.vols.push_back(
          surface.impliedVol(std::log(k / (100 * std::exp(rate * t))), t));
    }
  }
  return q;
}

TEST(SmileCalibrationTest, RecoversAnSsviSurface) {
  // With zero rates the forward is a quoted strike, so the at-the-money vols
  // are exact and the fit can be too.
  const auto fit = calibrateSsvi(ssviQuotes(0.0, -0.6, 1.1, 0.45));
  ASSERT_TRUE(fit.ok()) << fit.status();
  EXPECT_NEAR(-0.6, fit->rho, 1e-4);
  EXPECT_NEAR(1.1, fit->eta, 1e-3);
  EXPECT_NEAR(0.45, fit->gamma, 1e-3);
  EXPECT_LT(fit->rms_error, 1e-6);
  EXPECT_TRUE(fit->butterfly_ok);
  EXPECT_TRUE(fit->calendar_ok);
  EXPECT_FALSE(fit->thetas_adjusted);
}

TEST(SmileCalibrationTest, NearlyRecoversWithInterpolatedAtmVols) {
  // With rates, the forward falls between strikes: the at-the-money vols are
  // interpolated, so the fit is close rather than exact.
  const auto fit = calibrateSsvi(ssviQuotes(0.03, -0.6, 1.1, 0.45));
  ASSERT_TRUE(fit.ok()) << fit.status();
  EXPECT_NEAR(-0.6, fit->rho, 0.03);
  EXPECT_LT(fit->rms_error, 0.001);
}

// A skew that isn't SSVI: vol quadratic in standardised moneyness.
SmileQuotes quadraticSkew(double curvature) {
  SmileQuotes q{.spot = 100,
                .rate = 0.02,
                .expiries = kExpiries,
                .strikes = strikes(70, 130, 5)};
  const std::vector<double> atm{0.22, 0.20, 0.19, 0.185};
  for (size_t i = 0; i < kExpiries.size(); ++i) {
    const double t = kExpiries[i];
    for (double k : q.strikes) {
      const double m = std::log(k / (100 * std::exp(0.02 * t))) / std::sqrt(t);
      q.vols.push_back(atm[i] - 0.1 * m + curvature * m * m);
    }
  }
  return q;
}

TEST(SmileCalibrationTest, FitsANonSsviSkew) {
  const auto fit = calibrateSsvi(quadraticSkew(0.08));
  ASSERT_TRUE(fit.ok()) << fit.status();
  EXPECT_LT(fit->rho, 0);
  EXPECT_LT(fit->rms_error, 0.01);
  EXPECT_TRUE(fit->butterfly_ok);
  // Residuals are reported per quote, with both signs.
  int positive = 0;
  for (double r : fit->residuals) positive += r > 0;
  EXPECT_GT(positive, 0);
  EXPECT_LT(positive, std::ssize(fit->residuals));
}

TEST(SmileCalibrationTest, RefusesButterflyArbitrage) {
  // Enough curvature that the best unconstrained fit would admit arbitrage.
  const auto fit = calibrateSsvi(quadraticSkew(2.0));
  ASSERT_TRUE(fit.ok()) << fit.status();
  EXPECT_TRUE(fit->butterfly_ok);
}

TEST(SmileCalibrationTest, MakesAtmVarianceNonDecreasing) {
  SmileQuotes q = ssviQuotes(0.0, -0.5, 1, 0.4);
  // Make the 1-year at-the-money vol so low that total variance would fall.
  const size_t atm = 6;  // strike 100
  q.vols[2 * q.strikes.size() + atm] = 0.10;
  const auto fit = calibrateSsvi(q);
  ASSERT_TRUE(fit.ok()) << fit.status();
  EXPECT_TRUE(fit->thetas_adjusted);
  EXPECT_DOUBLE_EQ(fit->thetas[1], fit->thetas[2]);
  EXPECT_TRUE(fit->calendar_ok);
}

TEST(SmileCalibrationTest, SkipsMissingQuotes) {
  SmileQuotes q = ssviQuotes(0.0, -0.6, 1.1, 0.45);
  q.vols[0] = NAN;
  q.vols[5] = NAN;
  const auto fit = calibrateSsvi(q);
  ASSERT_TRUE(fit.ok()) << fit.status();
  EXPECT_TRUE(std::isnan(fit->fitted_vols[0]));
  EXPECT_TRUE(std::isnan(fit->residuals[5]));
  EXPECT_NEAR(-0.6, fit->rho, 1e-3);
}

void expectInvalid(const absl::Status& status, std::string_view message) {
  EXPECT_EQ(absl::StatusCode::kInvalidArgument, status.code()) << status;
  EXPECT_THAT(status.message(), testing::HasSubstr(message));
}

TEST(SmileCalibrationTest, ExplainsInvalidQuotes) {
  const SmileQuotes valid = ssviQuotes(0.0, -0.6, 1.1, 0.45);
  SmileQuotes q = valid;
  q.spot = 0;
  expectInvalid(calibrateSsvi(q).status(), "spot");
  q = valid;
  q.strikes = {100, 90};
  expectInvalid(calibrateSsvi(q).status(), "strictly increasing");
  q = valid;
  q.vols.pop_back();
  expectInvalid(calibrateSsvi(q).status(), "one entry per");
  q = valid;
  q.vols[3] = -0.1;
  expectInvalid(calibrateSsvi(q).status(), "positive");
  q = valid;
  for (double& v : q.vols) v = NAN;
  q.vols[0] = q.vols[1] = q.vols[2] = 0.2;
  expectInvalid(calibrateSsvi(q).status(), "at least four");
  q = valid;
  q.spot = 200;  // every strike below the forward
  expectInvalid(calibrateSsvi(q).status(), "bracket the forward");
}

}  // namespace
}  // namespace smileexplorer
